/// <summary>
/// Returns true when the vault already has Completed/ subdirectories with
/// any .md files (excluding INFO.md and README.md). Used to decide whether
/// to seed the ledger silently vs perform a full back-fill.
/// </summary>
private static bool HasCompletedNotes(ObsidianVaultLayout layout)
{
    var completedRoot = Path.Combine(layout.RepoDir, "Completed");
    if (!Directory.Exists(completedRoot)) return false;
    return Directory.EnumerateFiles(completedRoot, "*.md", SearchOption.AllDirectories)
        .Any(f => !ObsidianVaultLayout.ReservedFileNames.Contains(
            Path.GetFileName(f)));
}

